INSERT INTO faq_questions (question, answer, status, featured, published_at) VALUES ('Na czym polega doradztwo strategiczne dla firm?', '<p>Doradztwo strategiczne dla firm polega na uporządkowaniu kierunku rozwoju firmy, kluczowych decyzji właścicielskich oraz relacji między sprzedażą, marketingiem, produkcją i finansami. Celem jest stworzenie strategii dla firmy produkcyjnej, którą da się realnie wdrożyć w codziennym działaniu.</p>', 'published', 0, '2026-11-13T12:00:00.000Z');
INSERT INTO faq_questions (question, answer, status, featured, published_at) VALUES ('Czym różni się doradztwo strategiczne od standardowego konsultingu dla firm?', '<p>Standardowy konsulting dla firm często kończy się na analizie i rekomendacjach. Doradztwo strategiczne dla firm produkcyjnych idzie dalej, obejmuje diagnozę sytuacji, projektowanie rozwiązań, wdrażanie strategii i wspieranie firmy w utrzymaniu zmian w czasie.</p>', 'published', 0, '2026-11-13T11:59:00.000Z');
INSERT INTO faq_questions (question, answer, status, featured, published_at) VALUES ('Dla jakich firm jest przeznaczone doradztwo dla firm?', '<p>Doradztwo dla firm produkcyjnych jest przeznaczone przede wszystkim dla firm produkcyjnych i przemysłowych z sektora MŚP, które chcą uporządkować zarządzanie, zwiększyć rentowność, poprawić planowanie produkcji, wzmocnić sprzedaż B2B i odzyskać kontrolę nad rozwojem firmy.</p>', 'published', 0, '2026-11-13T11:58:00.000Z');
INSERT INTO faq_questions (question, answer, status, featured, published_at) VALUES ('Kiedy firma potrzebuje strategii?', '<p>Firma produkcyjna potrzebuje strategii wtedy, gdy rośnie przychód, ale jednocześnie pojawia się chaos decyzyjny, problemy z marżą, napięcia między sprzedażą a produkcją, słaba przewidywalność wyników albo przeciążenie właściciela. Strategia dla firmy produkcyjnej jest potrzebna także wtedy, gdy firma chce rosnąć bez utraty jakości i terminowości.</p>', 'published', 0, '2026-11-13T11:57:00.000Z');
INSERT INTO faq_questions (question, answer, status, featured, published_at) VALUES ('Ile kosztuje doradztwo strategiczne dla firm?', '<p>Koszt doradztwa strategicznego dla firm zależy od skali firmy, zakresu wsparcia, liczby obszarów do uporządkowania oraz tego, czy współpraca obejmuje tylko diagnozę, czy także wdrażanie strategii i wsparcie w działaniach operacyjnych. Ceny dopasowujemy do realiów mikro i małych przedsiębiorstw, ponieważ wiemy, że w tym segmencie budżet jest ograniczony i każda inwestycja musi być dobrze przemyślana oraz uzasadniona biznesowo.</p><p><a href="/#cennik">Więcej o kosztach znajdziesz tutaj</a></p>', 'published', 0, '2026-11-13T11:56:00.000Z');
INSERT INTO faq_questions (question, answer, status, featured, published_at) VALUES ('Czy doradztwo strategiczne jest dostępne także dla mikro i małych firm?', '<p>Tak. Współpracujemy również z mikro i małymi firmami, ponieważ to właśnie tam najczęściej potrzebne jest uporządkowanie strategii, sprzedaży, produkcji, innych działów i decyzji właścicielskich. Rozumiemy, że mniejsze firmy mają ograniczony budżet, dlatego zakres działań dobieramy tak, aby przynosił realny efekt i nie obciążał organizacji bardziej, niż to potrzebne.</p>', 'published', 0, '2026-11-13T11:55:00.000Z');
INSERT INTO faq_questions (question, answer, status, featured, published_at) VALUES ('Czy można dopasować zakres współpracy do budżetu firmy?', '<p>Tak. Zakres doradztwa dla firm można dopasować do aktualnej sytuacji firmy, jej priorytetów i możliwości finansowych. Zależy nam nie na tworzeniu dużych projektów za wszelką cenę, ale na tym, żeby firma produkcyjna otrzymała rozwiązania, które są potrzebne, możliwe do wdrożenia i opłacalne z perspektywy właściciela.</p>', 'published', 0, '2026-11-13T11:54:00.000Z');
INSERT INTO faq_questions (question, answer, status, featured, published_at) VALUES ('Czy doradztwo strategiczne pomaga połączyć sprzedaż, marketing i produkcję?', '<p>Tak. Jednym z głównych celów doradztwa strategicznego dla firm produkcyjnych jest połączenie strategii, sprzedaży, marketingu i realnych możliwości produkcyjnych. Dzięki temu firma nie sprzedaje więcej, niż jest w stanie dowieźć jakościowo, terminowo i z odpowiednią marżą.</p>', 'published', 0, '2026-11-13T11:53:00.000Z');
INSERT INTO faq_questions (question, answer, status, featured, published_at) VALUES ('Jakie problemy najczęściej rozwiązujecie w firmach?', '<p>Najczęściej pomagamy uporządkować decyzje właścicielskie, poprawić planowanie produkcji, ograniczyć straty wynikające z chaosu operacyjnego, zwiększyć skuteczność sprzedaży B2B dla firm produkcyjnych, uporządkować marketing dla firm oraz wdrożyć strategię, która nie kończy się na dokumencie.</p>', 'published', 0, '2026-11-13T11:52:00.000Z');
INSERT INTO faq_questions (question, answer, status, featured, published_at) VALUES ('Czy doradztwo strategiczne obejmuje optymalizację procesów produkcyjnych?', '<p>Tak, jeśli optymalizacja procesów produkcyjnych jest potrzebna do realizacji strategii firmy. W praktyce doradztwo strategiczne często dotyka takich obszarów jak efektywność operacyjna, przepływ informacji, planowanie, odpowiedzialność decyzyjna, kontrola kosztów produkcji i lepsze wykorzystanie zasobów.</p>', 'published', 0, '2026-11-13T11:51:00.000Z');
INSERT INTO faq_questions (question, answer, status, featured, published_at) VALUES ('Czy pomagacie właścicielom firm produkcyjnych odzyskać kontrolę nad firmą?', '<p>Tak. Doradztwo dla właścicieli firm produkcyjnych bardzo często dotyczy odzyskania kontroli nad firmą, ograniczenia roli właściciela jako wąskiego gardła i zbudowania bardziej przewidywalnego systemu zarządzania. Chodzi o to, żeby firma nie była zależna wyłącznie od bieżących decyzji jednej osoby.</p>', 'published', 0, '2026-11-13T11:50:00.000Z');
INSERT INTO faq_questions (question, answer, status, featured, published_at) VALUES ('Czy doradztwo strategiczne może pomóc zwiększyć marżę i ograniczyć koszty w firmie produkcyjnej?', '<p>Tak. Dobrze przygotowana strategia dla firmy produkcyjnej pomaga poprawić rentowność poprzez lepszą kontrolę kosztów produkcji, lepsze decyzje handlowe, bardziej świadome zarządzanie klientami, poprawę oferty oraz uporządkowanie procesów, które wpływają na marżę i wynik finansowy.</p>', 'published', 0, '2026-11-13T11:49:00.000Z');
INSERT INTO faq_questions (question, answer, status, featured, published_at) VALUES ('Czy wspieracie także sprzedaż i marketing dla firm produkcyjnych?', '<p>Tak. W wielu przypadkach doradztwo strategiczne obejmuje również sprzedaż B2B dla firm produkcyjnych i marketing dla firm produkcyjnych, ponieważ bez tych obszarów trudno zbudować spójny model wzrostu. Strategia musi uwzględniać nie tylko produkcję, ale też sposób pozyskiwania klientów i rozwijania rynku.</p>', 'published', 0, '2026-11-13T11:48:00.000Z');
INSERT INTO faq_questions (question, answer, status, featured, published_at) VALUES ('Jak wygląda współpraca w ramach doradztwa strategicznego dla firm?', '<p>Współpraca zwykle zaczyna się od rozmowy i diagnozy sytuacji firmy, następnie przechodzimy do określenia problemów, priorytetów i kierunku działań. Kolejny etap to projektowanie rozwiązań, wdrażanie strategii w firmie produkcyjnej oraz wsparcie we wprowadzaniu zmian w sprzedaży, marketingu, produkcji i zarządzaniu.</p>', 'published', 0, '2026-11-13T11:47:00.000Z');
